// scanFor returns wire slots.
func scanFor(l Layer, s Sym) []scanField {
	switch l {
	case L228:
		if f, ok := scanL228[s]; ok {
			return f
		}
	case L229:
		if f, ok := scanL229[s]; ok {
			return f
		}
	case L230:
		if f, ok := scanL230[s]; ok {
			return f
		}
	case L231:
		if f, ok := scanL231[s]; ok {
			return f
		}
	case L232:
		if f, ok := scanL232[s]; ok {
			return f
		}
	}
	return scanCanon[s]
}
